class Solution {
    public List<List<String>> partition(String s){List<List<String>>out=new ArrayList<>();dfs(s,0,new ArrayList<>(),out);return out;}
    private void dfs(String s,int start,List<String>p,List<List<String>>out){if(start==s.length()){out.add(new ArrayList<>(p));return;}for(int end=start;end<s.length();end++)if(pal(s,start,end)){p.add(s.substring(start,end+1));dfs(s,end+1,p,out);p.remove(p.size()-1);}}
    private boolean pal(String s,int l,int r){while(l<r)if(s.charAt(l++)!=s.charAt(r--))return false;return true;}
}

class Solution:
    def minCut(self, s: str) -> int:
        n=len(s);pal=[[False]*n for _ in range(n)];cuts=[0]*n
        for end in range(n):
            cuts[end]=end
            for start in range(end+1):
                if s[start]==s[end] and (end-start<2 or pal[start+1][end-1]):
                    pal[start][end]=True
                    cuts[end]=0 if start==0 else min(cuts[end],cuts[start-1]+1)
        return cuts[-1]

class Solution {
    public int minCut(String s){int n=s.length();boolean[][]pal=new boolean[n][n];int[]cuts=new int[n];for(int e=0;e<n;e++){cuts[e]=e;for(int st=0;st<=e;st++)if(s.charAt(st)==s.charAt(e)&&(e-st<2||pal[st+1][e-1])){pal[st][e]=true;cuts[e]=st==0?0:Math.min(cuts[e],cuts[st-1]+1);}}return cuts[n-1];}
}

