from functools import lru_cache

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        words=set(wordDict)
        @lru_cache(None)
        def build(i):
            if i==len(s):return ('',)
            out=[]
            for word in words:
                if s.startswith(word,i):
                    for suffix in build(i+len(word)):out.append(word if not suffix else word+' '+suffix)
            return tuple(out)
        return list(build(0))

