    private List<String> build(int i){if(memo.containsKey(i))return memo.get(i);List<String>out=new ArrayList<>();if(i==s.length()){out.add("");return out;}for(String w:words)if(s.startsWith(w,i))for(String suffix:build(i+w.length()))out.add(suffix.isEmpty()?w:w+" "+suffix);memo.put(i,out);return out;}
